// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Order, typedndarray, float64ndarray, float32ndarray, int32ndarray, int16ndarray, int8ndarray, uint32ndarray, uint16ndarray, uint8ndarray, uint8cndarray, boolndarray, complex128ndarray, complex64ndarray, genericndarray, DataType } from '@stdlib/types/ndarray';

/**
* Creates a two-dimensional array with ones on the kth diagonal and zeros elsewhere.
*
* ## Notes
*
* -   If the provided data type is complex, the function returns an ndarray whose kth diagonal is filled with complex numbers whose real component equals one and imaginary component equals zero
* -   If `k` is greater than the number of columns or less than the number of negative rows, the function returns an array filled with zeros
*
* @param dtype - underlying data type
* @param rows - number of rows
* @param cols - number of columns
* @param k - diagonal index. positive refers to upper diagonal, and negative refers to lower diagonal
* @param order - specifies whether an array is row-major (C-style) or column-major (Fortran-style)
* @returns output two-dimensional array
*
* @example
* var x = eye( 'float64', 3, 3, 0, 'row-major');
* // returns <ndarray>
*
* var sh =  x.shape;
* // returns [ 3, 3 ]
*
* var dt = x.dtype;
* // returns 'float64'
*
* var v = x.get( 0, 0 );
* // returns 1.0
*/
declare function eye( dtype: 'float64', rows: number, cols: number, k: number, order: Order ): float64ndarray;

